OLD={'blue_line_capital_group':'blue-line-capital-group','blue_line_exchange_blex':'blue-line-exchange','blue_line_property_management':'blue-line-property-management','blue_line_construction':'blue-line-construction','blue_line_sugar_manufacturing':'blue-line-sugar-manufacturing','blue_line_import_assembly_trade':'blue-line-import-assembly-trade','blue_line_finance_accounting':'group-finance-accounting','blue_line_hr_payroll':'hr-payroll'}
def route(l,slug=''):return f'/{l}/{slug.strip("/")}/' if slug else f'/{l}/'
def img(key,cls='',alt='Editorial illustration',hero=False):
 fallback,remote=MEDIA[key]
 # Primary editorial photography from Unsplash; offline artwork available and always included in the zip.
 return f'<img class="{E(cls)}" src="{E(remote)}" data-fallback="/assets/img/{E(fallback)}" alt="{E(alt)}" loading="{"eager" if hero else "lazy"}" decoding="async" {"fetchpriority=\"high\"" if hero else ""}>'
def topnav(l,active=''):
 t=I18N[l]; labels=t['nav']; hrefs=['', 'about','businesses','approach','careers','contact'];arr=[]
 for title,href in zip(labels,hrefs):
  uri=route(l,href);arr.append(f'<a href="{uri}" class="nav-link {"current" if href==active.split("/")[0] else ""}" {"aria-current=\"page\"" if href==active.split("/")[0] else ""}>{E(title)}</a>')
 return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="bar shell"><a class="brand" href="{route(l)}" aria-label="Blue Line Capital Group — Home"><img src="/assets/img/blue-line-logo.png" alt="Blue Line Capital Group" width="694" height="359"></a><nav class="desktop-nav" aria-label="Main navigation">{''.join(arr)}</nav><div class="header-right"><a class="lang-switch" href="{route('fr' if l=='en' else 'en',active)}" title="{'Passer en français' if l=='en' else 'Switch to English'}" aria-label="{'Passer en français' if l=='en' else 'Switch to English'}">{'FR' if l=='en' else 'EN'} <span aria-hidden="true">↗</span></a><a href="{route(l,'contact')}" class="nav-cta">{E(t['contact'])}<span aria-hidden="true">↗</span></a><button class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-menu"><span></span><span></span></button></div></div><nav id="mobile-menu" class="mobile-nav" aria-label="Mobile navigation" inert>{''.join(arr)}<a class="mobile-contact" href="{route(l,'contact')}">{E(t['contact'])} →</a></nav></header>'''
def footer(l):
 t=I18N[l];links=[('Our Group' if l=='en' else 'Le Groupe','about'),(t['nav'][2],'businesses'),(t['nav'][3],'approach'),(t['nav'][4],'careers'),(t['nav'][5],'contact')];lis=''.join(f'<a href="{route(l,k)}">{E(v)}</a>' for v,k in links)
 return f'''<footer class="site-footer"><div class="shell footer-grid"><div class="footer-brand"><a href="{route(l)}" aria-label="Home"><img src="/assets/img/blue-line-logo.png" width="694" height="359" alt="Blue Line Capital Group"></a><p>{E(t['footer'])}</p><span>DOUALA · CAMEROON</span></div><div><div class="footer-kicker">EXPLORE / DÉCOUVRIR</div><div class="footer-links">{lis}</div></div><div><div class="footer-kicker">IN CONVERSATION</div><a class="footer-mail" href="mailto:contact@bluelinecapitale.com">contact@bluelinecapitale.com ↗</a><p>{E(t['location'])}</p></div></div><div class="shell footer-bottom"><span>© <span id="year">2026</span> Blue Line Capital Group</span><span>Independent perspective · Connected enterprise</span><div><a href="{route(l,'privacy')}">{E(t['legal'])}</a> <a href="{route('fr' if l=='en' else 'en')}">{'FR' if l=='en' else 'EN'}</a></div></div></footer>'''
def html_page(l,section,title,description,body,og='hero-douala-concept.webp'):
 canonical=HOST+route(l,section);other='fr' if l=='en' else 'en';alt=HOST+route(other,section)
 css='/assets/styles.css';js='/assets/site.js'
 return f'''<!doctype html><html lang="{l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0b2030"><meta name="description" content="{E(description)}"><title>{E(title)} — Blue Line Capital Group</title><link rel="canonical" href="{E(canonical)}"><link rel="alternate" hreflang="en" href="{E(HOST+route('en',section))}"><link rel="alternate" hreflang="fr" href="{E(HOST+route('fr',section))}"><link rel="alternate" hreflang="x-default" href="{E(HOST+route('en',section))}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)} — Blue Line Capital Group"><meta property="og:description" content="{E(description)}"><meta property="og:url" content="{E(canonical)}"><meta property="og:image" content="{HOST}/assets/img/social-cover.jpg"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" as="style" href="{css}"><link rel="stylesheet" href="{css}"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'Organization','name':'Blue Line Capital Group','url':HOST,'logo':HOST+'/assets/img/blue-line-logo.png','address':{'@type':'PostalAddress','addressLocality':'Douala','addressCountry':'CM'}},ensure_ascii=False)}</script></head><body>{topnav(l,section)}<main id="main">{body}</main>{footer(l)}<script defer src="{js}"></script></body></html>'''
def write(l,section,title,description,body):
 p=SITE/l/section/'index.html' if section else SITE/l/'index.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html_page(l,section,title,description,body),encoding='utf-8')
