 t=I18N[l];hero=f'''<section class="hero"><div class="hero-art" aria-hidden="true"><img src="/assets/img/hero-douala-concept.webp" width="1500" height="1000" alt=""></div><div class="hero-shade"></div><div class="shell hero-content"><div>{label(t['eyebrow'],'00')}<h1>{E(t['hero'])}</h1><p>{E(t['herolead'])}</p><div class="hero-actions">{action(l,'businesses')}{action(l,'contact',t['get'],True)}</div></div><div class="hero-aside"><div class="hero-small">A GROUP WITH A LONG VIEW</div><span>CM / 04°03′ N · 09°42′ E</span></div></div><div class="hero-bottom shell"><span>DOUALA · CAMEROON</span><span>SCROLL TO EXPLORE <b aria-hidden="true">↓</b></span></div></section>'''
 intro=f'''<section class="intro section shell"><div class="intro-heading">{label(t['who'],'01')}<h2>{E(t['introhead'])}</h2></div><div class="intro-text"><p>{E(t['intro'])}</p><a href="{route(l,'about')}" class="text-link">{E(t['nav'][1])} <span aria-hidden="true">↗</span></a></div></section>'''
 featured=SECTORS[3];tag=featured['type_fr'] if l=='fr' else featured['type'];port=f'''<section class="portfolio section"><div class="shell"><div class="section-intro">{label(t['sector'],'02')}<div class="split-heading"><h2>{E(t['port'])}</h2><p>{E(t['portintro'])}</p></div></div><div class="feature-tile"><a class="feature-img" href="{route(l,'businesses/'+featured['slug'])}">{img('construction','',tag)}<span class="feature-image-overlay"></span><span class="feature-number">04 / 09</span></a><div class="feature-copy"><span class="small-label">FEATURED ACTIVITY / ACTIVITÉ</span><h3>{E(featured['headline_fr'] if l=='fr' else featured['headline'])}</h3><p>{E(featured['detail_fr'] if l=='fr' else featured['detail'])}</p><a class="text-link" href="{route(l,'businesses/'+featured['slug'])}">{E(t['read'])} ↗</a></div></div><div class="sector-grid">{cards(l,[SECTORS[i] for i in [1,2,4,5,7,8]])}</div><div class="section-action">{action(l,'businesses',t['viewall'])}</div></div></section>'''
 values=''.join(f'<article><span>0{i+1}</span><h3>{E(v)}</h3><p>{E(t["value_desc"][i])}</p></article>' for i,v in enumerate(t['values']))
 belief=f'''<section class="belief"><div class="belief-photo"><img src="/assets/img/approach-materials.webp" width="1500" height="1000" alt="Architectural visual concept of coordinated structures"></div><div class="belief-text">{label('THE BLUE LINE WAY','03')}<h2>{E(t['approach_title'])}</h2><p>{E(t['approach_intro'])}</p>{action(l,'approach',t['introcta'],True)}</div></section><section class="values-section section shell">{label(t['aboutprinciples'],'04')}<div class="values-grid">{values}</div></section>'''
 return hero+intro+port+belief+contactstrip(l)
