 return titlehero(l,'OUR GROUP / LE GROUPE',t['abouttitle'],t['aboutintro'],'group-strategy.webp')+f'''<section class="section shell two-col-editorial"><div>{label('01 / IDENTITY','02')}<h2>{E(t['about1'])}</h2></div><div><p class="large-copy">{E(t['aboutp1'])}</p><p>{E(t['aboutp2'])}</p></div></section><section class="wide-image"><div class="wide-img-inner">{img('group','', 'Business planning and office architecture')}</div>{imgcap(l)}</section><section class="section shell two-col-editorial"><div>{label('02 / STRUCTURE','03')}<h2>{E(t['about2'])}</h2></div><div><p class="large-copy">{E(t['aboutp3'])}</p><p>{E(t['intro'])}</p>{action(l,'businesses',t['viewall'])}</div></section><section class="values-section section shell">{label(t['aboutprinciples'],'04')}<div class="values-grid">{values}</div></section>'''+contactstrip(l)
