 return titlehero(l,'OUR APPROACH / NOTRE APPROCHE',t['approach_h'],t['approach_lead'],'approach-materials.webp')+f'''<section class="section shell approach-intro"><div>{label('HOW WE THINK','02')}<h2>{E(t['approach_title'])}</h2></div><div><p class="large-copy">{E(t['approach_intro'])}</p><p>{E(t['aboutp3'])}</p></div></section><section class="visual-break">{img('construction','', 'Construction site editorial photography')}{imgcap(l)}</section><section class="section shell"><div class="approach-steps">{steps}</div></section><section class="section shell compact-next"><div>{label('PORTFOLIO / ACTIVITÉS','04')}<h2>{E(t['port'])}</h2></div>{action(l,'businesses',t['viewall'])}</section>'''+contactstrip(l)
